import * as React from 'react';
import { cn } from '@/lib/utils';
import { Image } from '../image/Image';

export type CoverImageProps = {
  /** Cover URL. When absent or broken, the seeded fallback renders instead. */
  src?: string | null;
  /** Required: describes the image for assistive tech. */
  alt: string;
  /**
   * Aspect ratio: 'video' (16:9), 'square' (1:1), 'wide' (2:1), or any CSS
   * aspect-ratio value such as '16/9' or '4/3'.
   */
  aspect?: 'video' | 'square' | 'wide' | string;
  /** Stable key selecting the fallback gradient (e.g. entity slug). */
  seed?: string;
  /** Load eagerly and fetch at high priority for the LCP image. */
  priority?: boolean;
  /** Responsive `sizes` hint forwarded to the image. */
  sizes?: string;
  /** Custom fallback content; defaults to the seed-derived gradient. */
  fallback?: React.ReactNode;
  /** Optional mark centered on the default gradient (icon, monogram). */
  mark?: React.ReactNode;
  className?: string;
};

const aspectClasses = {
  video: 'aspect-video',
  square: 'aspect-square',
  wide: 'aspect-[2/1]',
} as const;

// Token-derived gradients: every entry uses theme variables so covers stay on
// the active palette in light and dark mode and pass the token audit.
const gradients = [
  'linear-gradient(135deg, hsl(var(--primary) / 0.18), hsl(var(--info) / 0.10))',
  'linear-gradient(135deg, hsl(var(--info) / 0.16), hsl(var(--primary) / 0.08))',
  'linear-gradient(135deg, hsl(var(--warning) / 0.14), hsl(var(--primary) / 0.10))',
  'linear-gradient(135deg, hsl(var(--success) / 0.14), hsl(var(--info) / 0.08))',
] as const;

function hashSeed(seed: string): number {
  let hash = 0;
  for (let i = 0; i < seed.length; i += 1) {
    hash = (hash * 31 + seed.charCodeAt(i)) >>> 0;
  }
  return hash;
}

function seededGradient(seed: string): React.CSSProperties {
  return { backgroundImage: gradients[hashSeed(seed) % gradients.length] };
}

/**
 * Media cover with a deterministic placeholder: a fixed-aspect box that shows
 * the image when present and a seed-derived token gradient (plus optional
 * mark) when the entity has no art. Broken images degrade to the same
 * gradient through Image's fallback chain, so imageless grids still look
 * intentional.
 */
export function CoverImage({
  src,
  alt,
  aspect = 'video',
  seed,
  priority = false,
  sizes,
  fallback,
  mark,
  className,
}: CoverImageProps) {
  const preset = aspectClasses[aspect as keyof typeof aspectClasses];
  const aspectStyle =
    preset === undefined && typeof aspect === 'string' ? { aspectRatio: aspect } : undefined;

  const fallbackNode =
    fallback ?? (
      <div
        className="flex h-full w-full items-center justify-center"
        style={seededGradient(seed ?? alt)}
        aria-hidden="true"
      >
        {mark && <span className="text-muted-foreground [&_svg]:size-8">{mark}</span>}
      </div>
    );

  return (
    <div
      className={cn('relative overflow-hidden rounded-lg bg-muted', preset, className)}
      style={aspectStyle}
    >
      {src ? (
        <Image
          src={src}
          alt={alt}
          priority={priority}
          sizes={sizes}
          fallback={fallbackNode}
          className="h-full w-full object-cover"
        />
      ) : (
        fallbackNode
      )}
    </div>
  );
}

CoverImage.displayName = 'CoverImage';

{
  "id": "cover-image",
  "name": "CoverImage",
  "tier": "molecule",
  "description": "Fixed-aspect media cover that shows the image when present and a deterministic seed-derived token gradient when the entity has no art.",
  "designIntent": "Media cards need a cover that never looks broken: imageless entities still get an intentional, per-entity placeholder instead of a reused generic social card. CoverImage wraps Image's src->fallback chain inside an aspect-ratio box so grids stay aligned and never shift layout.",
  "props": [
    {
      "name": "src",
      "type": "string | null",
      "required": false,
      "description": "Cover URL. When absent or broken, the seeded fallback renders instead.",
      "examples": [
        "https://cdn.example.com/events/fall-classic.jpg"
      ]
    },
    {
      "name": "alt",
      "type": "string",
      "required": true,
      "description": "Accessible description of the image."
    },
    {
      "name": "aspect",
      "type": "'video' | 'square' | 'wide' | string",
      "required": false,
      "defaultValue": "video",
      "enum": [
        "video",
        "square",
        "wide"
      ],
      "description": "Aspect ratio: presets map to 16:9, 1:1 and 2:1; any CSS aspect-ratio value like '16/10' also works.",
      "examples": [
        "square",
        "16/10"
      ]
    },
    {
      "name": "seed",
      "type": "string",
      "required": false,
      "description": "Stable key selecting the fallback gradient (e.g. entity slug), so the same entity always gets the same placeholder."
    },
    {
      "name": "priority",
      "type": "boolean",
      "required": false,
      "defaultValue": "false",
      "description": "Load eagerly and fetch at high priority for the LCP image."
    },
    {
      "name": "sizes",
      "type": "string",
      "required": false,
      "description": "Responsive sizes hint forwarded to the image element."
    },
    {
      "name": "fallback",
      "type": "React.ReactNode",
      "required": false,
      "description": "Custom fallback content; defaults to the seed-derived token gradient."
    },
    {
      "name": "mark",
      "type": "React.ReactNode",
      "required": false,
      "description": "Optional mark (icon, monogram) centered on the default gradient."
    },
    {
      "name": "className",
      "type": "string",
      "required": false,
      "description": "Classes merged onto the aspect-ratio container."
    }
  ],
  "examples": [
    {
      "title": "Entity cover with seeded placeholder",
      "code": "<CoverImage\n  src={event.imageUrl}\n  alt={event.title}\n  seed={event.slug}\n  aspect=\"video\"\n  sizes=\"(min-width: 1024px) 33vw, 100vw\"\n/>",
      "description": "16:9 cover; imageless events get a stable per-slug gradient."
    },
    {
      "title": "Square avatar-style cover",
      "code": "<CoverImage alt={studio.name} seed={studio.slug} aspect=\"square\" mark={<StudioIcon />} />",
      "description": "Square cover with a mark on the gradient fallback."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't use it for photos of people",
      "explanation": "Use Avatar for people and firms; CoverImage is for media covers (events, articles, listings).",
      "example": "// Avoid\n<CoverImage src={person.photo} alt={person.name} />\n\n// Prefer\n<Avatar src={person.photo} name={person.name} />"
    },
    {
      "title": "Don't skip the seed",
      "explanation": "Without a stable seed the fallback falls back to alt text, so two entities can share a gradient by accident. Pass the entity slug.",
      "example": "<CoverImage src={e.image} alt={e.title} seed={e.slug} />"
    }
  ],
  "accessibility": [
    {
      "feature": "Image semantics",
      "implementation": "Renders a real img with alt when src is present; the gradient fallback is aria-hidden decoration",
      "userRequirements": "Always pass a descriptive alt; the placeholder is not content"
    },
    {
      "feature": "Layout stability",
      "implementation": "The aspect-ratio box reserves space before the image loads, so grids never shift",
      "userRequirements": "Pick the aspect that matches the card design"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Alt text",
      "guidelines": [
        "Describe the image, not the component",
        "For decorative covers paired with a title, keep alt concise"
      ],
      "goodExamples": [
        "Fall Classic competition floor"
      ],
      "badExamples": [
        "Cover image",
        "Photo"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "Card",
      "relationship": "CoverImage is the media slot at the top of a Card or listing tile",
      "example": "<Card><CoverImage src={item.image} alt={item.title} seed={item.slug} /><CardContent>…</CardContent></Card>"
    },
    {
      "component": "Image",
      "relationship": "CoverImage wraps Image, inheriting its src->fallbackSrc->fallback resilience chain",
      "example": "<CoverImage src={url} alt={alt} />"
    }
  ],
  "relatedComponents": [
    "Image",
    "Avatar",
    "Card"
  ],
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.11.6",
  "sourceDir": "cover-image",
  "exportName": "CoverImage"
}
